public void init()
{
    next init();
    this.metEnableControl();
}

public void metEnableControl()
{

    FormRun formRunCaller = this.args().caller();
    FormDataSource fds = formRunCaller.dataSource(formDataSourceStr(GUPPriceRebatePriceAttributeGroupEdit, TAMRebateTable));

    if(formRunCaller.args().menuItemName() == menuitemdisplaystr(TAMRebateDealListPageVendRebate))
    {
        fds.object(fieldNum(TAMRebateTable, RebateAgreementType)).enabled(false);
    }
    else
    {
        fds.object(fieldNum(TAMRebateTable, RebateAgreementType)).enabled(true);
    }
}
